/**
 * Platform field-value shapes — used as record / task-output types so
 * `DeepRef` exposes the sub-properties the Elementum platform resolves at
 * runtime (e.g. `ctx.trigger.record.owner.email` → ref name `user.email`).
 *
 * These are value types, not deployable entity kinds. Org `user`/`group`
 * modules are data lookups for org.ts; these interfaces describe USER/GROUP
 * (etc.) *field values* on records.
 */
export interface Manager {
    readonly name: string;
    readonly email: string;
}
export interface Employee {
    readonly manager: Manager;
}
export interface User {
    readonly id: string;
    readonly name: string;
    readonly email: string;
    readonly employee: Employee;
}
export interface Group {
    readonly id: string;
    readonly name: string;
}
export interface Attachment {
    readonly id: string;
    readonly name: string;
    readonly description: string;
    readonly mediaType: string;
    readonly url: string;
}
/**
 * A rich-text value. The platform exposes both `plainText` (stripped) and
 * `html` (the rendered HTML) sub-properties on rich-text references.
 */
export interface RichText {
    readonly plainText: string;
    readonly html: string;
}
/** A selected Dropdown option. Multi-Select fields expose an array of these. */
export interface DropdownValue {
    readonly id: string;
    readonly label: string;
}
declare const recordIdBrand: unique symbol;
/** Platform record identity (wire type ASPECT_RECORD_ID). */
export type RecordId = string & {
    readonly [recordIdBrand]: "recordId";
};
/**
 * A dynamically sourced Dropdown selection. It retains the normal Dropdown
 * option id/label and also exposes the selected source record's identity.
 */
export interface DynamicDropdownValue extends DropdownValue {
    readonly recordId: RecordId;
}
export {};
